try:
    import numpy as np
    from scipy import stats as sp_stats
    skip_cols = {'order_id'}
    anomaly_records = []
    for col in ['revenue', 'units', 'discount', 'marketing_spend']:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = 0
        if abs(skew) > 2:
            shift = -float(s.min()) if float(s.min()) < 0 else 0
            s_work = np.log1p(s + shift)
        else:
            s_work = s.copy()
        q1, q3 = s_work.quantile(0.25), s_work.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (s_work < lo3) | (s_work > hi3)
        frac = mask.sum() / len(s_work)
        if frac > 0.05:
            orig_lo = float(np.expm1(lo3) - shift) if abs(skew) > 2 else float(lo3)
            orig_hi = float(np.expm1(hi3) - shift) if abs(skew) > 2 else float(hi3)
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'{orig_lo:.4g} to {orig_hi:.4g}',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-boundary flags exceed 5% of values'
            })
            continue
        flagged_idx = s_work[mask].index
        for idx in flagged_idx:
            orig_val = float(df.loc[idx, col])
            w = s_work.loc[idx]
            orig_lo = float(np.expm1(lo3) - shift) if abs(skew) > 2 else float(lo3)
            orig_hi = float(np.expm1(hi3) - shift) if abs(skew) > 2 else float(hi3)
            if w < lo5 or w > hi5:
                sev = 'critical'
            elif w < lo4 or w > hi4:
                sev = 'high'
            else:
                sev = 'medium'
            exp_range = f'{orig_lo:.4g} to {orig_hi:.4g}'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': orig_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {orig_val} lies outside expected range {exp_range}'
            })
    anomaly_records = anomaly_records[:25]
    result['anomalies'].extend(anomaly_records)
except Exception:
    pass

