    monthly_rev = df.groupby('_ym')['revenue'].sum().sort_index()
    if len(monthly_rev) >= 3:
        x = np.arange(len(monthly_rev))
        y = monthly_rev.values.astype(float)
        coeffs = np.polyfit(x, y, 1)
        next_periods = [str(monthly_rev.index[-1] + i) for i in range(1, 4)]
        for i, p in enumerate(next_periods, start=1):
            pred = float(np.polyval(coeffs, len(monthly_rev) - 1 + i))
            result['forecast_points'].append({'period': p, 'value': round(pred, 2)})
