try:
    import numpy as np
    from scipy import stats as sp_stats
    anomaly_records = []
    for col in metrics:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = -s.min() if s.min() < 0 else 0
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (s_t < lo3) | (s_t > hi3)
        frac = mask.sum() / len(s_t)
        if frac > 0.05:
            orig_lo = float(np.expm1(lo3) - shift) if abs(skew) > 2 else float(lo3)
            orig_hi = float(np.expm1(hi3) - shift) if abs(skew) > 2 else float(hi3)
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'[{orig_lo:.2f}, {orig_hi:.2f}]',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-boundary flagging skipped'
            })
            continue
        flagged = s_t[mask]
        for idx in flagged.index[:25]:
            orig_val = float(df.loc[idx, col])
            t_val = s_t.loc[idx]
            if abs(skew) > 2:
                orig_lo = float(np.expm1(lo3) - shift)
                orig_hi = float(np.expm1(hi3) - shift)
            else:
                orig_lo, orig_hi = float(lo3), float(hi3)
            if t_val > hi5 or t_val < lo5:
                sev = 'critical'
            elif t_val > hi4 or t_val < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            exp_range = f'[{orig_lo:.2f}, {orig_hi:.2f}]'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': orig_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {orig_val} lies outside expected range {exp_range}'
            })
    result['anomalies'] = anomaly_records[:25]
except Exception:
    pass

