        lo4, hi4 = Q1 - 4*IQR, Q3 + 4*IQR
        lo5, hi5 = Q1 - 5*IQR, Q3 + 5*IQR
        mask = (s_t < lo3) | (s_t > hi3)
        frac = mask.sum() / len(s_t)
        if frac > 0.05:
            if abs(skew) > 2:
                orig_lo = float(np.expm1(lo3) - shift)
                orig_hi = float(np.expm1(hi3) - shift)
            else:
                orig_lo, orig_hi = float(lo3), float(hi3)
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'{orig_lo:.3f} to {orig_hi:.3f}',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-boundary flags exceed 5% of rows, column skipped for individual anomalies'
            })
            total_anomalies += 1
            continue
        flagged = s_t[mask]
        for idx in flagged.index:
            if total_anomalies >= 25:
                break
            val_t = s_t[idx]
            orig_val = float(df.loc[idx, col])
            if abs(skew) > 2:
                orig_lo_val = float(np.expm1(lo3) - shift)
                orig_hi_val = float(np.expm1(hi3) - shift)
            else:
                orig_lo_val, orig_hi_val = float(lo3), float(hi3)
            if val_t > hi5 or val_t < lo5:
                sev = 'critical'
            elif val_t > hi4 or val_t < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            er = f'{orig_lo_val:.3f} to {orig_hi_val:.3f}'
            result['anomalies'].append({
                'column': col, 'row_index': int(idx), 'value': orig_val,
                'expected_range': er, 'severity': sev,
                'explanation': f'{col} value {orig_val} lies outside expected range {er}'
            })
            total_anomalies += 1
except Exception:
    pass

