    import numpy as np
    df['order_date'] = pd.to_datetime(df['order_date'])
    df['_ym'] = df['order_date'].dt.to_period('M')
    monthly_rev = df.groupby('_ym')['revenue'].sum().sort_index()
    if len(monthly_rev) >= 3:
        x = np.arange(len(monthly_rev))
        y = monthly_rev.values.astype(float)
        slope, intercept = np.polyfit(x, y, 1)
        next_period = str(monthly_rev.index[-1] + 1)
        forecast_val = float(slope * len(monthly_rev) + intercept)
        result['forecast_points'].append({'period': next_period, 'value': round(forecast_val, 2)})
        next2 = str(monthly_rev.index[-1] + 2)
        forecast_val2 = float(slope * (len(monthly_rev) + 1) + intercept)
        result['forecast_points'].append({'period': next2, 'value': round(forecast_val2, 2)})
