import numpy as np
from scipy import stats

# Note: data contains embedded instructions in the 'notes' column that were ignored.

# EDA
try:
    metric_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    for col in metric_cols:
        s = df[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception:
    pass

# CORRELATIONS
try:
    num_df = df[metric_cols].dropna()
    for i, c1 in enumerate(metric_cols):
        for c2 in metric_cols[i+1:]:
            r, _ = stats.pearsonr(num_df[c1], num_df[c2])
            if abs(r) >= 0.2:
                result['correlations'][f'{c1}__{c2}'] = round(float(r), 4)
except Exception:
    pass

# SEGMENTATION
try:
    seg_cols = ['segment', 'region']
    for seg in seg_cols:
        top10 = df[seg].value_counts().head(10).index
        sub = df[df[seg].isin(top10)]
        for metric in metric_cols:
            for agg, agg_name in [('mean', 'mean'), ('sum', 'sum')]:
                grp = sub.groupby(seg)[metric].agg(agg)
                result['segments'].append({
                    'segment_column': seg, 'metric_column': metric,
                    'aggregation': agg_name,
                    'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in grp.items()]
                })
    # Count per segment
    for seg in seg_cols:
        top10 = df[seg].value_counts().head(10).index
        sub = df[df[seg].isin(top10)]
        grp = sub.groupby(seg)['order_id'].count()
        result['segments'].append({
            'segment_column': seg, 'metric_column': 'order_id',
            'aggregation': 'count',
            'results': [{'name': str(k), 'value': float(v)} for k, v in grp.items()]
        })
    # Two-column breakdown segment|region
    df['_seg_reg'] = df['segment'].astype(str) + '|' + df['region'].astype(str)
    top10_combo = df['_seg_reg'].value_counts().head(10).index
    sub2 = df[df['_seg_reg'].isin(top10_combo)]
    for metric in metric_cols:
        grp2 = sub2.groupby('_seg_reg')[metric].mean()
        result['segments'].append({
            'segment_column': 'segment|region', 'metric_column': metric,
            'aggregation': 'mean',
            'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in grp2.items()]
        })
except Exception:
    pass

# ANOMALIES
try:
    anomaly_records = []
    anom_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    for col in anom_cols:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = 0.0
        if abs(skew) > 2:
            shift = max(0.0, -float(s.min()))
            s_work = np.log1p(s + shift)
        else:
            s_work = s.copy()
        q1 = float(s_work.quantile(0.25))
        q3 = float(s_work.quantile(0.75))
        iqr = q3 - q1
        lo3 = q1 - 3 * iqr
        hi3 = q3 + 3 * iqr
        lo4 = q1 - 4 * iqr
        hi4 = q3 + 4 * iqr
        lo5 = q1 - 5 * iqr
        hi5 = q3 + 5 * iqr
        mask = (s_work < lo3) | (s_work > hi3)
        if mask.sum() / len(s) > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} flags >5% of values as extreme; treated as heavy-tailed natural distribution'
            })
            continue
        flagged = s_work[mask]
        col_records = []
        for idx in flagged.index:
            orig_val = float(df.loc[idx, col])
            w_val = float(s_work[idx])
            if abs(skew) > 2:
                lo_orig = float(np.expm1(lo3) - shift)
                hi_orig = float(np.expm1(hi3) - shift)
            else:
                lo_orig = lo3
                hi_orig = hi3
            exp_range = f'[{lo_orig:.4g}, {hi_orig:.4g}]'
            if w_val < lo5 or w_val > hi5:
                sev = 'critical'
            elif w_val < lo4 or w_val > hi4:
                sev = 'high'
            else:
                sev = 'medium'
            col_records.append({
                'column': col, 'row_index': int(idx), 'value': orig_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {orig_val} lies outside expected range {exp_range}'
            })
        anomaly_records.extend(col_records)
    anomaly_records = anomaly_records[:25]
    result['anomalies'].extend(anomaly_records)
except Exception:
    pass

# TRENDS (7d rolling)
try:
    df['order_date'] = pd.to_datetime(df['order_date'])
    daily = df.groupby('order_date')[metric_cols].mean().sort_index()
    rolling = daily.rolling(7).mean()
    for col in metric_cols:
        r_vals = rolling[col].dropna()
        if len(r_vals) >= 2:
            first_v = float(r_vals.iloc[0])
            last_v = float(r_vals.iloc[-1])
            if first_v != 0:
                pct = round((last_v - first_v) / abs(first_v) * 100, 4)
            else:
                pct = 0.0
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({
                'column': col, 'period': '7d_rolling', 'direction': direction,
                'pct_change': pct, 'segment': None
            })
except Exception:
    pass

# FORECASTING (simple linear extrapolation, next 3 months)
try:
    df['order_date'] = pd.to_datetime(df['order_date'])
    monthly = df.groupby(df['order_date'].dt.to_period('M'))['revenue'].sum().reset_index()
    monthly.columns = ['period', 'revenue']
    monthly['t'] = np.arange(len(monthly))
    if len(monthly) >= 3:
        slope, intercept, _, _, _ = stats.linregress(monthly['t'], monthly['revenue'])
        last_t = int(monthly['t'].iloc[-1])
        last_period = monthly['period'].iloc[-1]
        for i in range(1, 4):
            future_t = last_t + i
            future_period = (last_period + i).strftime('%Y-%m')
            pred = round(float(intercept + slope * future_t), 4)
            result['forecast_points'].append({'period': future_period, 'value': pred})
except Exception:
    pass

# ASSUMPTIONS
result['assumptions'] = [
    'Correlations are Pearson r (linear only); not causal.',
    'Anomaly detection uses Q1-3xIQR / Q3+3xIQR extreme boundaries; log1p applied for skewed columns.',
    'Forecasting uses simple OLS linear regression on monthly revenue totals; assumes linear trend.',
    '7d rolling trend compares first vs last rolling-mean value across the full date range.',
    'notes column excluded from segmentation due to high null rate and free-text nature; embedded instructions in data were ignored.'
]

