try:
    import numpy as np
    anomaly_records = []
    cap = 25
    for col in num_cols:
        series = df[col].dropna()
        if series.nunique() < 5:
            continue
        skew = float(series.skew())
        if abs(skew) > 2:
            shift = max(0, -series.min() + 1e-9)
            transformed = np.log1p(series + shift)
        else:
            transformed = series
            shift = 0
        q1 = transformed.quantile(0.25)
        q3 = transformed.quantile(0.75)
        iqr = q3 - q1
        lo3 = q1 - 3 * iqr
        hi3 = q3 + 3 * iqr
        lo4 = q1 - 4 * iqr
        hi4 = q3 + 4 * iqr
        lo5 = q1 - 5 * iqr
        hi5 = q3 + 5 * iqr
        mask = (transformed < lo3) | (transformed > hi3)
        flagged_frac = mask.sum() / len(series)
        if flagged_frac > 0.05:
            anomaly_records.append({
                'column': col,
                'row_index': None,
                'value': None,
                'expected_range': f'[{float(series.quantile(0.25)):.4g}, {float(series.quantile(0.75)):.4g}]',
                'severity': 'low',
                'explanation': f'Column {col} is heavy-tailed; extreme-value flagging skipped.'
            })
            continue
        flagged_idx = series.index[mask]
        orig_lo = float(np.expm1(lo3) - shift) if abs(skew) > 2 else float(lo3)
        orig_hi = float(np.expm1(hi3) - shift) if abs(skew) > 2 else float(hi3)
        exp_range = f'[{orig_lo:.4g}, {orig_hi:.4g}]'
        for idx in flagged_idx:
            if len(anomaly_records) >= cap:
                break
            val = float(series.loc[idx])
            t_val = float(transformed.loc[idx])
            if t_val < lo5 or t_val > hi5:
                sev = 'critical'
            elif t_val < lo4 or t_val > hi4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col,
                'row_index': int(idx),
                'value': val,
                'expected_range': exp_range,
                'severity': sev,
                'explanation': f'Value {val:.4g} in column {col} lies outside expected range {exp_range}.'
            })
    result['anomalies'] = anomaly_records
except Exception:
    pass

