        skew = float(series.skew())
        if abs(skew) > 2:
            shift = max(0, -series.min() + 1e-9)
            transformed = np.log1p(series + shift)
        else:
            transformed = series
            shift = 0
        q1 = transformed.quantile(0.25)
        q3 = transformed.quantile(0.75)
        iqr = q3 - q1
        lo3 = q1 - 3 * iqr
        hi3 = q3 + 3 * iqr
        lo4 = q1 - 4 * iqr
        hi4 = q3 + 4 * iqr
        lo5 = q1 - 5 * iqr
        hi5 = q3 + 5 * iqr
        mask = (transformed < lo3) | (transformed > hi3)
        flagged_frac = mask.sum() / len(series)
        if flagged_frac > 0.05:
            anomaly_records.append({
                'column': col,
                'row_index': None,
                'value': None,
                'expected_range': f'[{float(series.quantile(0.25)):.4g}, {float(series.quantile(0.75)):.4g}]',
                'severity': 'low',
                'explanation': f'Column {col} is heavy-tailed; extreme-value flagging skipped.'
