    import numpy as np
    from statsmodels.tsa.holtwinters import ExponentialSmoothing
    df['order_date'] = pd.to_datetime(df['order_date'])
    monthly_rev = df.groupby(df['order_date'].dt.to_period('M'))['revenue'].sum().sort_index()
